package com.bank.band.service;

import java.util.Collections;
import java.util.PriorityQueue;
import java.util.logging.Logger;

// Sums elements ranked strictly between the K1-th and K2-th smallest.
public class BalanceBandService {
    private static final Logger log = Logger.getLogger(BalanceBandService.class.getName());

    public long sumBetween(int[] balances, int k1, int k2) {
        // size-K2 max-heap keeps the K2 smallest; root = K2-th smallest
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        for (int b : balances) {
            maxHeap.offer(b);
            if (maxHeap.size() > k2) maxHeap.poll(); // keep only K2 smallest
        }
        maxHeap.poll();                 // discard the K2-th smallest (excluded)
        long sum = 0;
        while (maxHeap.size() > k1) {   // leave the K1 smallest (excluded)
            sum += maxHeap.poll();      // these are ranks K1+1 .. K2-1
        }
        final long result = sum;
        log.info(() -> "Sum between " + k1 + "th and " + k2 + "th smallest = " + result);
        return sum;
    }
}
