package com.bank.band;

import com.bank.band.service.BalanceBandService;
import java.util.logging.Logger;

public class BalanceBandApplication {
    private static final Logger log = Logger.getLogger(BalanceBandApplication.class.getName());

    public static void main(String[] args) {
        BalanceBandService service = new BalanceBandService();
        int[] balances = {1000, 3000, 12000, 5000, 15000, 7000};
        // sorted: 1000,3000,5000,7000,12000,15000; between 2nd and 5th smallest → 5000+7000
        log.info("Mid-tier balance sum: " + service.sumBetween(balances, 2, 5));
    }
}
